class NabTabs{constructor(){}static resetSelected(target_buttons,target_content){try{document.querySelectorAll(target_buttons).forEach(e=>{e.classList.remove("active")}),document.querySelectorAll(target_buttons)[0].classList.add("active"),document.querySelectorAll(target_content).forEach(e=>{e.classList.remove("show"),e.classList.remove("active")}),document.querySelectorAll(target_content)[0].classList.add("show"),document.querySelectorAll(target_content)[0].classList.add("active")}catch(Exception){console.log("Se produjo un error...")}}}export{NabTabs};